/** agent id → 品牌标记。没有登记的 agent 回落到通用图标，不报错。 */
const MARKS: Record<string, ComponentType<MarkProps>> = {
  "claude-code": ClaudeMark,
  codex: OpenAIMark,
  opencode: OpenCodeMark,
  pi: PiMark,
  grok: GrokMark,
  "deepseek-harness": DeepSeekMark,
};

/**
 * 按 agent 取品牌标记的组件形态，给只接受组件类型的插槽用
 * （例如 `EmptyState` 的 icon）。返回的是 map 里的稳定引用，
 * 不会每次渲染都造一个新组件类型导致重挂载。
 */
export function agentIcon(agentId: string): ComponentType<MarkProps> {
  return MARKS[agentId] ?? Boxes;
}

/** 导航／设置使用 md，来源统计／卡片／弹窗使用 sm；共享品牌留白校准。 */
export function AgentIcon({
  agentId,
  size = "md",
  className,
}: {
  agentId: string;
  size?: "sm" | "md";
  className?: string;
}) {
  const Mark = agentIcon(agentId);
  return (
    <Mark
      className={cn(
        "shrink-0",
        size === "sm" ? "h-4 w-4" : "h-5 w-5",
        className,
      )}
    />
  );
}
